svg.script:
(function(){
  var blob = document.getElementById('blob');
  var win = (typeof window !== 'undefined' && window.parent && window.parent !== window) ? window.parent : window;
  var raf = null;
  function buildPath(t){
    var cx=30, cy=30, baseR=19, N=36, d='';
    for (var i=0; i<=N; i++){
      var a = (i/N) * Math.PI * 2;
      var noise = Math.sin(a*3 + t*1.4)*3.2 + Math.cos(a*5 + t*0.9)*2.4 + Math.sin(a*7 + t*0.6)*1.2;
      var r = baseR + noise;
      var x = cx + Math.cos(a)*r;
      var y = cy + Math.sin(a)*r;
      d += (i===0 ? 'M ' : ' L ') + x.toFixed(2) + ',' + y.toFixed(2);
    }
    return d + ' Z';
  }
  function paint(){
    var y = win.scrollY || 0;
    blob.setAttribute('d', buildPath(y * 0.012));
  }
  win.addEventListener('scroll', function(){
    if (raf) cancelAnimationFrame(raf);
    raf = requestAnimationFrame(paint);
  }, { passive: true });
  paint();
})();
